    if (absolutePath) {
        path = path.substring(1);
    }
    int start = 0;
    int i = 0;
    while (i < path.length()) {
        if (path.charAt(i) == '/') {
            if (i > start) {
                String segment = path.substring(start, i);
                if (decode) {
                    segment = URLDecoder.decode(segment, "UTF-8");
                }
                segments.add(new PathSegmentImpl(segment, absolutePath, decode));
                start = i + 1;
            }
        }
        i++;
    }
